import sys
from itertools import permutations
sys.setrecursionlimit(10000)

def solve(N, gates):
    best = [10 ** 18]
    free = [True] * (N + 2)

    def run(order, gi, total):
        if total >= best[0]:
            return
        if gi == 3:
            best[0] = total
            return
        pos, f = order[gi]

        def place(left, total):
            if left == 0:
                run(order, gi + 1, total)
                return
            d = 0
            while True:
                cand = []
                l, r = pos - d, pos + d
                if l >= 1 and free[l]:
                    cand.append(l)
                if r <= N and r != l and free[r]:
                    cand.append(r)
                if cand:
                    break
                d += 1
            if left == 1:
                for s in cand:
                    free[s] = False
                    place(0, total + d + 1)
                    free[s] = True
            else:
                s = cand[0]
                free[s] = False
                place(left - 1, total + d + 1)
                free[s] = True

        place(f, total)

    for order in permutations(gates):
        run(order, 0, 0)
    return best[0]

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    idx = 1
    out = []
    for _ in range(t):
        N = int(data[idx]); idx += 1
        gates = []
        for _ in range(3):
            gates.append((int(data[idx]), int(data[idx + 1])))
            idx += 2
        out.append(str(solve(N, gates)))
    print('\n'.join(out))

main()

