def gen(rng):
    def case(N, gates):
        return f'{N}\n' + '\n'.join(f'{p} {f}' for p, f in gates)

    def fmt(cases):
        return str(len(cases)) + '\n' + '\n'.join(cases)

    def rand_case(N, fill):
        pos = rng.sample(range(1, N + 1), 3)
        total = max(3, int(N * fill))
        total = min(total, N)
        counts = [1, 1, 1]
        for _ in range(total - 3):
            counts[rng.randrange(3)] += 1
        return case(N, list(zip(pos, counts)))

    sample = [case(10, [(4, 5), (6, 2), (10, 2)]), case(10, [(8, 5), (9, 1), (10, 2)]), case(24, [(15, 3), (20, 4), (23, 7)]),
              case(39, [(17, 8), (30, 5), (31, 9)]), case(60, [(57, 12), (31, 19), (38, 16)])]
    tests = [fmt([case(5, [(2, 2), (3, 1), (5, 1)])]), fmt([case(3, [(1, 1), (2, 1), (3, 1)])]),
             fmt([case(3, [(2, 1), (1, 1), (3, 1)])]), fmt([case(6, [(3, 2), (4, 2), (2, 2)])]),
             fmt([case(7, [(4, 3), (1, 2), (7, 2)])]), fmt([case(4, [(2, 2), (3, 1), (4, 1)])]),
             fmt([case(8, [(4, 4), (5, 2), (6, 2)])])]
    for _ in range(22):
        cs = []
        for _ in range(rng.randint(1, 2)):
            N = rng.randint(3, 8)
            cs.append(rand_case(N, rng.choice([0.4, 0.7, 1.0])))
        tests.append(fmt(cs))
    for _ in range(4):
        cs = [rand_case(rng.randint(60, 100), rng.choice([0.5, 0.9, 1.0])) for _ in range(20)]
        tests.append(fmt(cs))
    tests.append(fmt(sample * 5))
    tests.append(fmt([rand_case(100, 1.0) for _ in range(20)]))
    tests.append(fmt([case(100, [(50, 34), (51, 33), (52, 33)]) for _ in range(20)]))
    tests.append(fmt([case(100, [(10, 40), (99, 40), (55, 20)]) for _ in range(20)]))
    return tests

